local PRODUCTS = {
    iron_annealing_tongs = { name = "Železne klešče za žarjenje", ironCost = 4, woodCost = 1, leatherCost = 1, time = 5, cost = 190, prestige = 3, happiness = 2, description = "Železne klešče za žarjenje stekla." },
    bronze_annealing_tongs = { name = "Bronaste klešče za žarjenje", bronzeCost = 4, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 460, prestige = 5, happiness = 3, description = "Bronaste klešče za varno žarjenje." },
    silver_annealing_tongs = { name = "Srebrne klešče za žarjenje", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1110, prestige = 10, happiness = 4, description = "Srebrne klešče za plemiške steklarje." },
    gilded_annealing_tongs = { name = "Pozlačene klešče za žarjenje", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2380, prestige = 19, happiness = 5, description = "Pozlačene klešče za dvorne steklarje." },
    jewel_set_annealing_tongs = { name = "Draguljaste klešče za žarjenje", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 5100, prestige = 35, happiness = 7, description = "Draguljaste klešče za kraljeve steklarje." },
    royal_sovereign_annealing_tongs = { name = "Kraljevski suverene klešče za žarjenje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 10900, prestige = 68, happiness = 13, description = "Suverene klešče z biseri za krono." },
}
local BUILDINGS = {
    annealingtongs_workshop = { name = "Kleščna delavnica", cost = { gold = 365, wood = 175, stone = 145, iron = 10 }, upkeep = 7, qualityBonus = 5 },
    annealingtongs_house = { name = "Kleščna hiša", cost = { gold = 1275, wood = 360, stone = 285, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_annealingtongs_atelier = { name = "Mojstrski kleščni atelje", cost = { gold = 3180, wood = 420, stone = 540, silver = 38, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_annealingtongs_palace = { name = "Suverena kleščna palača", cost = { gold = 13500, wood = 645, stone = 855, gold = 87, jewel = 20 }, upkeep = 262, qualityBonus = 55, prestigeBonus = 50 },
}
AnnealingTongsMaker.ironStock = 16; AnnealingTongsMaker.bronzeStock = 12; AnnealingTongsMaker.woodStock = 10; AnnealingTongsMaker.leatherStock = 10; AnnealingTongsMaker.silverStock = 8; AnnealingTongsMaker.goldStock = 6; AnnealingTongsMaker.jewelStock = 4; AnnealingTongsMaker.pearlStock = 4
AnnealingTongsMaker.productStock = {}; AnnealingTongsMaker.buildings = {}; AnnealingTongsMaker.maker = nil; AnnealingTongsMaker.activeMaking = {}; AnnealingTongsMaker.totalProducts = 0; AnnealingTongsMaker.dayTimer = 0
function AnnealingTongsMaker.init() AnnealingTongsMaker.ironStock=16; AnnealingTongsMaker.bronzeStock=12; AnnealingTongsMaker.woodStock=10; AnnealingTongsMaker.leatherStock=10; AnnealingTongsMaker.silverStock=8; AnnealingTongsMaker.goldStock=6; AnnealingTongsMaker.jewelStock=4; AnnealingTongsMaker.pearlStock=4; AnnealingTongsMaker.productStock={}; AnnealingTongsMaker.buildings={}; AnnealingTongsMaker.maker=nil; AnnealingTongsMaker.activeMaking={}; AnnealingTongsMaker.totalProducts=0; AnnealingTongsMaker.dayTimer=0; print("[AnnealingTongsMaker] Royal Annealing Tongs Maker System initialized (6 products, 4 buildings)") end
function AnnealingTongsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AnnealingTongsMaker.maker={name=n or ("Kleščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kleščar najet: %s (spretnost: %d)",AnnealingTongsMaker.maker.name,s),"success") end; return true end
function AnnealingTongsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AnnealingTongsMaker.build(id) local ok,e=AnnealingTongsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AnnealingTongsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AnnealingTongsMaker.getQualityBonus() local b=0; for _,bd in ipairs(AnnealingTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AnnealingTongsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AnnealingTongsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AnnealingTongsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AnnealingTongsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AnnealingTongsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AnnealingTongsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AnnealingTongsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AnnealingTongsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AnnealingTongsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AnnealingTongsMaker.buildings==0 then return false,"Potrebna kleščna delavnica" end; if not AnnealingTongsMaker.maker then return false,"Potreben kleščar" end; return true end
function AnnealingTongsMaker.make(pt,qty) qty=qty or 1; local ok,e=AnnealingTongsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AnnealingTongsMaker.ironStock=AnnealingTongsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AnnealingTongsMaker.bronzeStock=AnnealingTongsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AnnealingTongsMaker.woodStock=AnnealingTongsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AnnealingTongsMaker.leatherStock=AnnealingTongsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AnnealingTongsMaker.silverStock=AnnealingTongsMaker.silverStock-d.silverCost*qty end; if d.goldCost then AnnealingTongsMaker.goldStock=AnnealingTongsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AnnealingTongsMaker.jewelStock=AnnealingTongsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AnnealingTongsMaker.pearlStock=AnnealingTongsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AnnealingTongsMaker.maker then t=math.max(1,t-math.floor(AnnealingTongsMaker.maker.skill/13)) end; table.insert(AnnealingTongsMaker.activeMaking,{id="annealingtongs_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AnnealingTongsMaker.completeMaking(m) local q=1.0+(AnnealingTongsMaker.getQualityBonus()/100); if AnnealingTongsMaker.maker then q=q+(AnnealingTongsMaker.maker.skill/140) end; q=math.min(2.5,q); AnnealingTongsMaker.productStock[m.productType]=(AnnealingTongsMaker.productStock[m.productType] or 0)+m.quantity; AnnealingTongsMaker.totalProducts=AnnealingTongsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AnnealingTongsMaker.maker then AnnealingTongsMaker.maker.itemsMade=AnnealingTongsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AnnealingTongsMaker.maker.skill=math.min(100,AnnealingTongsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klešče izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"annealingtongs.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AnnealingTongsMaker.update(dt) if not _G.state then return end; AnnealingTongsMaker.dayTimer=AnnealingTongsMaker.dayTimer+dt; if AnnealingTongsMaker.dayTimer>=30 then AnnealingTongsMaker.dayTimer=0; for i=#AnnealingTongsMaker.activeMaking,1,-1 do local m=AnnealingTongsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AnnealingTongsMaker.completeMaking(m); table.remove(AnnealingTongsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AnnealingTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AnnealingTongsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AnnealingTongsMaker.getStats() return {ironStock=AnnealingTongsMaker.ironStock,bronzeStock=AnnealingTongsMaker.bronzeStock,woodStock=AnnealingTongsMaker.woodStock,leatherStock=AnnealingTongsMaker.leatherStock,silverStock=AnnealingTongsMaker.silverStock,goldStock=AnnealingTongsMaker.goldStock,jewelStock=AnnealingTongsMaker.jewelStock,pearlStock=AnnealingTongsMaker.pearlStock,productStock=AnnealingTongsMaker.productStock,numBuildings=#AnnealingTongsMaker.buildings,hasMaker=AnnealingTongsMaker.maker~=nil,makerName=AnnealingTongsMaker.maker and AnnealingTongsMaker.maker.name or "—",makerSkill=AnnealingTongsMaker.maker and AnnealingTongsMaker.maker.skill or 0,activeMaking=#AnnealingTongsMaker.activeMaking,totalProducts=AnnealingTongsMaker.totalProducts} end
return AnnealingTongsMaker
